UPDATE ${table}
SET occupied = occupied + #{amount}, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND occupied + frozen + #{amount} <= total_amount

UPDATE ${table}
SET occupied = occupied - #{amount}, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND occupied >= #{amount}

UPDATE ${table}
SET frozen = frozen + #{amount}, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND occupied + frozen + #{amount} <= total_amount

UPDATE ${table}
SET frozen = frozen - #{amount}, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND frozen >= #{amount}

UPDATE ${table}
SET frozen = frozen - #{amount}, occupied = occupied + #{amount},
    gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND frozen >= #{amount}

UPDATE ${table}
SET total_amount = total_amount + #{delta}, gmt_modified = CURRENT_TIMESTAMP
WHERE quota_key = #{quotaKey} AND total_amount + #{delta} >= occupied + frozen
